import { EXPORT_COUNTRIES, SUPPLY_CITIES } from "./countriesData";

// src/types/productMaterial.types.ts

export interface ProductMaterial {
  // Core fields (required)
  id: number;
  slug: string;
  image: string;
  title: string;
  shortDescription: string;

  // Optional core fields
  materialGroup?: string;
  standards?: string;
  forms?: string;
  application?: string;

  // Add to ProductMaterial interface
astmSpecifications?: Array<{
  standard: string;
  description: string;
}>;

// Add to ProductMaterial interface
supplyRange?: Array<{
  description: string;
  wallThickness: string;
  outsideDiameter: string;
}>;

  // Extended fields for stainless-steel-coils and other detailed products
  technicalOverview?: string;

  // Flexible gradeDetails - supports multiple structures
  gradeDetails?: {
    standardAustenitic?: Record<string, string>;
    highTemperature?: Record<string, string>;
    specializedCorrosion?: Record<string, string>;
    standardGrades?: Record<string, string>;
    [key: string]: any;
  };

  manufacturingStandards?: {
    specifications?: string;
    forms?: string[];
  };

  // Flexible specifications - supports different key names
  specifications?: {
    standard?: string;
    thicknessRange?: string;
    widthLength?: string;
    widthRange?: string;
    surfaceFinish?: string;
    formHardness?: string;
    hardnessTemper?: string;
    formLength?: string;
    valueAddedServices?: string;
    testCertificate?: string;
    [key: string]: any;
  };

  // Stock Availability - supports any category structure
  stockAvailability?: {
    hotRolled?: StockCategory[];
    coldRolled?: StockCategory[];
    slitStrip?: StockCategory[];
    [key: string]: any;
  };

  stockCategory?: StockCategory;

  equivalentGrades?: Array<{
    grade: string;
    uns: string;
    wnr?: string;
    werkstoff?: string;
    jis?: string;
    bs?: string;
    gost?: string;
    afnor?: string;
    en?: string;
    enJisAfnor?: string;
    commonName?: string;
    common?: string;
    sis?: string;
    din?: string;
    iso?: string;
    ks?: string;
    or?: string;
    sa?: string;
    sae?: string;
    astm?: string;
    standard?: string;
    uns_no?: string;
    [key: string]: any; // Allows ANY additional fields
  }>;

  // Flexible chemicalComposition - supports different elements
  chemicalComposition?: Array<{
    grade: string;
    c?: string;
    mn?: string;
    si?: string;
    cr?: string;
    ni?: string;
    mo?: string;
    ti?: string;
    al?: string;
    v?: string;
    fe?: string;
    o?: string;
    other?: string;
    [key: string]: any;
  }>;

  // Flexible mechanicalProperties - supports different fields
  mechanicalProperties?: Array<{
    grade: string;
    tensile?: string;
    yield?: string;
    elongation?: string;
    density?: string;
    [key: string]: any;
  }>;

  // Flexible thicknessAvailability
  thicknessAvailability?: Array<{
    thickness: string;
    availability?: string;
    widthUpTo36?: string;
    widthUpTo48?: string;
    [key: string]: any;
  }>;

  // Flexible weight charts
  weightSizeCharts?: {
    coldRolledDescaled?: Array<{ size: string; weight: string }>;
    finish1D?: Array<{ size: string; weight: string }>;
    [key: string]: any;
  };

  // Flexible weight chart (supports both pipes and coils)
  weightSizeChart?: Array<{
    thickness?: string;
    weightPerM2?: string;
    size2000?: string;
    size2500?: string;
    size3000?: string;
    nps?: string;
    od_in?: string;
    od_mm?: string;
    wall_in?: string;
    wall_mm?: string;
    sched?: string;
    kg_mtr?: string;
    lb_ft?: string;
    [key: string]: any;
  }>;

  // Flexible gauge chart
  gaugeChart?: Array<{
    gauge: string;
    inches: string;
    mm: string;
    [key: string]: any;
  }>;

  // Flexible specialty weight chart
  specialtyWeightChart?: Array<{
    thickness: string;
    weightPerM2: string;
    size2000: string;
    size2500: string;
    size3000: string;
    [key: string]: any;
  }>;

   // Size and Dimensions (for Titanium Round Bars)
  sizeDimensions?: Array<{
    metric_size?: string;
    diameter_mm?: string;
    us_rods?: string;
    us_diameter_inch?: string;
    japanese_rods?: string;
    japanese_diameter_mm?: string;
    [key: string]: any;
  }>;
   
  // Flexible thickness tolerance - supports multiple formats
  thicknessTolerance?: Array<{
    // For pipe format (existing)
    thickness?: string;
    widthUpTo36?: string;
    widthUpTo48?: string;

    // For titanium plate format (new)
    width?: string;
    thickness_2_5_4_5?: string;
    thickness_6?: string;
    thickness_8?: string;
    thickness_10?: string;
    thickness_12_5?: string;
    thickness_16?: string;
    thickness_20?: string;
    thickness_25?: string;
    thickness_30?: string;
    thickness_gt_30?: string;

    // Allow any additional fields
    [key: string]: any;
  }>;

  // ✅ PRICE RANGE - Matches your exact data structure
  priceRange?: Array<{
    // Option 1: Standard format (designation)
    designation?: string;

    // Option 2: Diameter format (diameter_in + designation_a)
    diameter_in?: string;
    designation_a?: string;

    // Common fields across all formats
    od_mm?: string;
    weight_kg_mtr?: string;
    wall_thk_mm?: string;
    price_inr_mtr?: string;
    price_inr_kg?: string;

    // Additional fields that might exist
    sch_10s?: string;
    schedule?: string;
    [key: string]: any; // For any other future fields
  }>;

  jindalPriceList?: Array<{
    nominalBore_mm: string;
    nominalBore_inch: string;
    od_mm: string;
    sch5s_wt_mm: string;
    sch5s_price_kg: string;
    sch10s_wt_mm: string;
    sch10s_price_kg: string;
    sch40s_wt_mm: string;
    sch40s_price_kg: string;
    [key: string]: any;
  }>;

  tataPriceList?: Array<any>;
  sailPriceList?: Array<any>;

  // Arrays for various lists
  specializedIn?: string[];
  relatedSearches?: string[];
  exportCountries?: string[];
  supplyCities?: string[];

  // For other products that might have different structures
  keyFeatures?: string[];
  features?: string[];
  applications?: string[];

  // Allows any additional fields
  [key: string]: any;
}

// Stock Category Interface
export interface StockCategory {
  title?: string;
  items?:
    | string[]
    | Array<{ name: string; description?: string; image?: string }>;
  image?: string;
  [key: string]: any;
}

